# Part-3 plates and props prompts. Run: python stil/canli/prompts/make_p3_pl.py
import os

HERE = os.path.dirname(os.path.abspath(__file__))
HEAD = "Use your built-in image_gen tool to generate exactly ONE image, 16:9 landscape. Do not copy or move any files and do not run shell commands; just generate it, then print DONE.\n\n"
STYLE = "Match the attached style reference EXACTLY: flat silk-screen print, navy #18203A shapes with thin cream #F3EFE4 trim lines, moon-yellow #F0D35A accents, fine grain, slight misregistration. "
FLAT = "FLAT FRONT ELEVATION: no perspective, no vanishing lines, camera at chest height, every facade exactly parallel to the picture plane (a camera will later track sideways along it). "
NOPEOPLE = "NO people, NO figures, NO mannequins, NO silhouettes of humans. ABSOLUTELY NO text, letters, numbers, logos or watermarks anywhere (shop signs are blank plain boards). "
SKY = "The SKY above the roofline is ONE flat solid pure magenta (#FF00FF), completely uniform, no clouds, no sun, no gradient; the magenta appears ONLY as sky above the roofs (never inside windows). The window glass shows a dim navy interior with moon-yellow pendant lamps and shelves, fully opaque (NOT magenta). A strip of pale cream sidewalk along the bottom edge. Each facade's far left and far right edge is a plain vertical navy pilaster (so copies can be placed side by side). Palette only navy, cream, moon yellow (+ the magenta sky). No 3D render look, no photorealism, no soft shading.\n"
BGM = "\n\nBackground: ONE flat solid pure magenta (#FF00FF), completely uniform, no shadow, no floor line, no ground. ABSOLUTELY NO text, letters, numbers, logos, watermarks, no people. Palette only navy, cream, moon yellow (+ magenta background). No 3D render look, no photorealism, no soft shading.\n"

def strip(a, b, ca, cb):
    return (HEAD + STYLE + FLAT + NOPEOPLE + "Draw a strip of two old town SHOP FRONTS side by side filling the whole width: " + a + " on the left and " + b + " on the right. " + ca + cb +
            " Ground-floor shop windows wide and tall, navy facades with cream trim, one storey of small windows above each, a roofline with chimneys near the top. " + SKY)

P = {}
P['p3-pl-shops-a'] = strip("a CLOTHING shop (a rail of shirts hanging in the window, shelves of folded cloth)", "a BAKERY (shelves of loaves and a tray of rolls)", "", "")
P['p3-pl-shops-b'] = strip("a BOOKSHOP (shelves full of books, a stack on a table)", "a FLOWER shop (buckets of flowers and potted plants in the window)", "", "")
P['p3-pl-tv'] = (HEAD + STYLE + FLAT + NOPEOPLE + "Draw ONE old TV AND RADIO SHOP FRONT filling the width: one big shop window; behind the glass a wall of 10 old CRT television sets (a few small old radios between them) stacked on shelves, in rows. EVERY television SCREEN is ONE flat solid pure magenta (#FF00FF) rectangle, completely empty (no picture, no glare), framed by the navy TV casing; these screen holes are the ONLY magenta except the sky. Navy facade with cream trim, a roofline with chimneys near the top, one storey of small windows above. " + SKY.replace("the magenta appears ONLY as sky above the roofs (never inside windows).", "the magenta appears only as the sky above the roofs and as the empty television screens.").replace("The window glass shows a dim navy interior with moon-yellow pendant lamps and shelves, fully opaque (NOT magenta).", "Behind the glass a dim navy interior with a moon-yellow pendant lamp, fully opaque."))
P['p3-pl-cafe'] = (HEAD + STYLE + "Reference composition: the attached image shows a café window seen from the sidewalk; draw the SAME composition and viewpoint but with NO people at all. " + NOPEOPLE +
    "Left about 45% of the width: the street outside by day, cream sky, trees with moon-yellow leaves, distant facades, sidewalk. A thick vertical navy window frame stands at about 45-50% of the width. To the right of it the café interior seen through the glass: dark navy, a moon-yellow pendant lamp, small round tables with chairs, a cup on a saucer on a table. Faint vertical streak highlights on the glass. The whole image is fully opaque, NO magenta anywhere. Palette only navy, cream, moon yellow. No 3D render look, no photorealism.\n")
P['p3-pl-table'] = (HEAD + "Attached: (1) the APPROVED desk of this film's side-view room, drawn in an eye-level FRONT ELEVATION; (2) the room itself. Match the style and the eye-level front elevation of image 1 EXACTLY: flat silk-screen print, navy #18203A shapes with thin cream #F3EFE4 rim lines, moon-yellow accents, fine grain, slight misregistration (wood tones only as navy and a little yellow-cream).\n\n"
    "Draw ONE isolated PROP, centred, nothing cropped: a plain wooden WORKTABLE in FRONT ELEVATION at eye level: the tabletop is a thin slab seen almost edge-on, TWO straight vertical legs at the two ends, both ending on ONE straight horizontal floor line. The space between the legs is empty. The top is EMPTY: no monitor, no objects, nothing on it. Proportions about 3.2 to 1 wide to high including the legs. No chair, no person, no floor shadow." + BGM)
P['p3-pl-props'] = (HEAD + STYLE + "Draw TWO separate isolated objects side by side with clear empty space between them, NOT touching, same flat front elevation, same scale as a street: on the LEFT a street TREE (navy trunk, a leafy crown of navy and moon-yellow leaves, as in the reference) standing on its base; on the RIGHT an old cast-iron street LAMP POST (navy, slim fluted column, a lantern head with a moon-yellow glow). Both have a bottom base line at about the same height. Nothing cropped, no ground, no shadow." + BGM)
P['p3-pl-table-r1'] = P['p3-pl-table'].replace('Proportions about 3.2 to 1 wide to high including the legs.', 'The previous attempt had legs that were too long. Proportions: STRICTLY 3.2 to 1 wide to high measured over the whole drawing including the legs (for example 1400 px wide and 440 px high): SHORT legs, the legs only about as long as three times the thickness of the tabletop apron.')
for k, v in P.items():
    open(os.path.join(HERE, k + '.txt'), 'w', encoding='utf8').write(v)
print(len(P), 'prompts')
